create extension if not exists pgcrypto;
create table if not exists public.pro_cases (id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,client_case_id text not null,title text not null,manufacturer text,model text,serial text,appliance_type text,technical_question text,notes text,source_json jsonb not null default '{}'::jsonb,manual_json jsonb not null default '{}'::jsonb,manual_identity_hash text,conversation_json jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,client_case_id));
create table if not exists public.pro_case_sources (id uuid primary key default gen_random_uuid(),case_id uuid not null references public.pro_cases(id) on delete cascade,owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,sha256 text not null check (sha256 ~ '^[a-f0-9]{64}$'),file_name text not null,mime_type text not null,byte_size bigint not null check (byte_size >= 0),page_count integer,text_truncated boolean not null default false,source_role text not null check (source_role in ('manual','listing_label','inspection_report','field_photo','other')),technician_note text,storage_path text,integrity_status text not null default 'unchecked' check (integrity_status in ('unchecked','verified','mismatch','missing')),created_at timestamptz not null default now(),unique(case_id,sha256));
create table if not exists public.pro_case_revisions (id uuid primary key default gen_random_uuid(),case_id uuid not null references public.pro_cases(id) on delete cascade,owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,snapshot_json jsonb not null,revision_reason text not null default 'client_sync',created_at timestamptz not null default now());
alter table public.pro_cases enable row level security; alter table public.pro_case_sources enable row level security; alter table public.pro_case_revisions enable row level security;
drop policy if exists "owners manage own pro cases" on public.pro_cases; create policy "owners manage own pro cases" on public.pro_cases for all using (auth.uid()=owner_id) with check (auth.uid()=owner_id);
drop policy if exists "owners manage own case sources" on public.pro_case_sources; create policy "owners manage own case sources" on public.pro_case_sources for all using (auth.uid()=owner_id) with check (auth.uid()=owner_id);
drop policy if exists "owners read own revisions" on public.pro_case_revisions; create policy "owners read own revisions" on public.pro_case_revisions for select using (auth.uid()=owner_id);
drop policy if exists "owners create own revisions" on public.pro_case_revisions; create policy "owners create own revisions" on public.pro_case_revisions for insert with check (auth.uid()=owner_id);
insert into storage.buckets (id,name,public) values ('pro-case-sources','pro-case-sources',false) on conflict (id) do nothing;
drop policy if exists "owners upload pro case sources" on storage.objects; create policy "owners upload pro case sources" on storage.objects for insert to authenticated with check (bucket_id='pro-case-sources' and exists (select 1 from public.pro_cases c where c.id=((storage.foldername(name))[2])::uuid and c.owner_id=auth.uid()));
drop policy if exists "owners read pro case sources" on storage.objects; create policy "owners read pro case sources" on storage.objects for select to authenticated using (bucket_id='pro-case-sources' and exists (select 1 from public.pro_cases c where c.id=((storage.foldername(name))[2])::uuid and c.owner_id=auth.uid()));
